import cliForge from 'cli-forge';

const cli = cliForge('object-arguments', {
  builder: (args) =>
    args.option('config', {
      type: 'object',
      description: 'Configuration object with nested properties',
      properties: {
        server: {
          type: 'object',
          description: 'Server configuration',
          properties: {
            host: {
              type: 'string',
              description: 'Server hostname',
              default: 'localhost',
            },
            port: {
              type: 'number',
              description: 'Server port',
              default: 3000,
            },
            ssl: {
              type: 'boolean',
              description: 'Enable SSL',
              default: false,
            },
          },
        },
        database: {
          type: 'object',
          description: 'Database configuration',
          properties: {
            host: {
              type: 'string',
              description: 'Database hostname',
              required: true, // This will only be required if database config is provided
            },
            port: {
              type: 'number',
              description: 'Database port',
              default: 5432,
            },
            name: {
              type: 'string',
              description: 'Database name',
              required: true, // This will only be required if database config is provided
            },
          },
        },
        features: {
          type: 'array',
          items: 'string',
          description: 'Enabled features',
          default: ['basic'],
        },
      },
      // You can provide a default for the entire config object
      default: {
        server: {
          host: 'localhost',
          port: 3000,
          ssl: false,
        },
        features: ['basic'],
      },
      // Validate the entire config object
      validate: (config) => {
        if (
          config.server?.port &&
          (config.server.port < 1 || config.server.port > 65535)
        ) {
          return 'Server port must be between 1 and 65535';
        }
        return true;
      },
      // Coerce can transform the final config object
      coerce: (config) => {
        // Add a computed property - use type assertion since we're extending the type
        if (config.server) {
          (config.server as { url?: string }).url = `${
            config.server.ssl ? 'https' : 'http'
          }://${config.server.host}:${config.server.port}`;
        }
        return config as typeof config & { server?: { url: string } };
      },
    }),
  handler: (args) => {
    console.log('Configuration:');
    console.log(JSON.stringify(args.config, null, 2));

    // Type-safe access to nested properties
    if (args.config?.server) {
      console.log(`\nServer will run at: ${args.config.server.url}`);
    }

    if (args.config?.database) {
      console.log(
        `Database: ${args.config.database.name} at ${args.config.database.host}:${args.config.database.port}`
      );
    }

    if (args.config?.features) {
      console.log(`Features: ${args.config.features.join(', ')}`);
    }
  },
});

// We export the CLI for a few reasons:
// - Testing
// - Composition (a CLI can be a subcommand of another CLI)
// - Docs generation
export default cli;

// Calling `.forge()` executes the CLI. It's single parameter is the CLI args
// and they default to `process.argv.slice(2)`.
if (require.main === module) {
  (async () => {
    await cli.forge();
  })();
}

